CREATE TABLE IF NOT EXISTS gis_phase351_admin_reconciliation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, candidate_id UUID NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_admin_level TEXT, target_admin_level TEXT, source_parent TEXT, target_parent TEXT, source_boundary_version TEXT, target_boundary_version TEXT, admin_level_match BOOLEAN NOT NULL DEFAULT false, parent_match BOOLEAN NOT NULL DEFAULT false, boundary_version_match BOOLEAN NOT NULL DEFAULT false, reconciliation_status TEXT NOT NULL, issues JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,candidate_id));